'use strict';

import utils from '../utils.js';
import parseHeaders, {normalizeHeaderKey, isMultiValueHeader} from '../helpers/parseHeaders.js';
import bind from '../helpers/bind.js';

const $internals = Symbol('internals');
const $defaults = Symbol('defaults');

function normalizeHeader(header) {
  return header && String(header).trim().toLowerCase();
}

function normalizeValue(value) {
  if (value === false || value == null) {
    return value;
  }

  return String(value);
}

function parseTokens(str) {
  const tokens = Object.create(null);
  const tokensRE = /([^\s,;=]+)\s*(?:=\s*([^,;]+))?/g;
  let match;

  while ((match = tokensRE.exec(str))) {
    tokens[match[1]] = match[2];
  }

  return tokens;
}

function matchHeaderValue(context, value, header, filter) {
  if (utils.isFunction(filter)) {
    return filter.call(this, value, header);
  }

  if (!utils.isString(value)) return;

  if (utils.isString(filter)) {
    return value.indexOf(filter) !== -1;
  }

  if (utils.isRegExp(filter)) {
    return filter.test(value);
  }
}

function formatHeader(header) {
  return header.trim()
    .toLowerCase().replace(/([a-z\d])(\w*)/g, (w, char, str) => {
      return char.toUpperCase() + str;
    });
}

function buildAccessors(obj, header) {
  const accessorName = utils.toCamelCase(' ' + header);

  ['get', 'set', 'has'].forEach(methodName => {
    Object.defineProperty(obj, methodName + accessorName, {
      value: function(arg1, arg2, arg3) {
        return this[methodName].call(this, header, arg1, arg2, arg3);
      },
      configurable: true
    });
  });
}

function findKey(obj, key) {
  key = key.toLowerCase();
  const keys = Object.keys(obj);
  let i = keys.length;
  let _key;
  while (i-- > 0) {
    _key = keys[i];
    if (key === _key.toLowerCase()) {
      return _key;
    }
  }
  return null;
}

function AxiosHeaders(headers, defaults) {
  headers && this.set(headers);
  this[$defaults] = defaults || null;
}

Object.assign(AxiosHeaders.prototype, {
  set: function(header, valueOrRewrite, rewrite) {
    const self = this;
    const pendingEntries = [];
    const objectTag = Object.prototype.toString;
    const boundPush = bind(pendingEntries.push, pendingEntries);
    let rewriteFlag = rewrite;
    let isHeaderMap = false;

    if (header != null) {
      if (typeof header === 'object') {
        const headerTag = objectTag.call(header);
        if (headerTag === '[object Object]') {
          const headerProto = Object.getPrototypeOf(header);
          const objectProto = Object.prototype;
          const parentProto = headerProto ? Object.getPrototypeOf(headerProto) : null;
          if (headerProto === null) {
            isHeaderMap = true;
          } else if (headerProto === objectProto) {
            isHeaderMap = true;
          } else if (parentProto === null) {
            isHeaderMap = true;
          } else {
            isHeaderMap = false;
          }
          if (isHeaderMap) {
            if (Symbol.toStringTag in header) {
              isHeaderMap = false;
            } else if (Symbol.iterator in header) {
              isHeaderMap = false;
            }
          }
        } else {
          isHeaderMap = false;
        }
      } else {
        isHeaderMap = false;
      }
    } else {
      isHeaderMap = false;
    }

    if (isHeaderMap || utils.isPlainObject(header)) {
      const headerNames = Object.keys(header);
      const headerCount = headerNames.length;
      if (headerCount > 0) {
        for (let headerIndex = 0; headerIndex < headerCount; headerIndex++) {
          const entryName = headerNames[headerIndex];
          const entryValue = header[entryName];
          const collectedName = entryName;
          const collectedValue = entryValue;
          const collected = {
            name: collectedName,
            value: collectedValue
          };
          boundPush(collected);
        }
      }
      rewriteFlag = valueOrRewrite;
    } else {
      const singleEntry = {
        name: header,
        value: valueOrRewrite
      };
      boundPush(singleEntry);
    }

    const workingEntries = [];
    const pendingCount = pendingEntries.length;
    for (let copyIndex = 0; copyIndex < pendingCount; copyIndex++) {
      const sourceEntry = pendingEntries[copyIndex];
      const clonedEntry = {
        name: sourceEntry.name,
        value: sourceEntry.value
      };
      workingEntries.push(clonedEntry);
    }

    const entryCount = workingEntries.length;
    for (let entryIndex = 0; entryIndex < entryCount; entryIndex++) {
      const entry = workingEntries[entryIndex];
      if (entry === undefined) {
        continue;
      }

      let _header = entry.name;
      let _value = entry.value;
      const _rewrite = rewriteFlag;
      const importedKey = normalizeHeaderKey(_header);
      const localKey = normalizeHeader(_header);
      let lHeader = importedKey;
      if (!lHeader) {
        lHeader = localKey;
      }

      if (!lHeader) {
        throw new Error('header name must be a non-empty string');
      }

      let key = null;
      const ownedKeys = Object.keys(self);
      const ownedCount = ownedKeys.length;
      let ownedIndex = ownedCount;
      const loweredHeader = String(lHeader).toLowerCase();
      if (ownedCount > 0) {
        while (ownedIndex-- > 0) {
          const candidate = ownedKeys[ownedIndex];
          if (candidate != null) {
            const candidateText = String(candidate);
            const loweredCandidate = candidateText.toLowerCase();
            if (loweredHeader === loweredCandidate) {
              key = candidate;
              break;
            }
          }
        }
      }

      if (key == null) {
        const fallbackKey = findKey(self, lHeader);
        if (fallbackKey) {
          key = fallbackKey;
        }
      }

      if (key && _rewrite !== true && (self[key] === false || _rewrite === false)) {
        continue;
      }

      const cookieHeader = isMultiValueHeader(_header);
      const valueTag = objectTag.call(_value);
      let prepared = _value;

      if (utils.isArray(_value)) {
        const copied = [];
        const valueLength = _value.length;
        for (let valueIndex = 0; valueIndex < valueLength; valueIndex++) {
          const item = _value[valueIndex];
          const itemTag = objectTag.call(item);
          if (item === false || item == null) {
            copied.push(item);
          } else if (cookieHeader) {
            if (utils.isString(item)) {
              if (item.indexOf('=') !== -1) {
                if (item.indexOf(';') !== -1) {
                  const delimiter = ';';
                  const attributes = item.split(delimiter);
                  const attrCount = attributes.length;
                  const rebuilt = new Array(attrCount);
                  for (let attrIndex = 0; attrIndex < attrCount; attrIndex++) {
                    const rawAttr = attributes[attrIndex];
                    rebuilt[attrIndex] = rawAttr;
                  }
                  const rebuiltCookie = rebuilt.join(delimiter);
                  copied.push(rebuiltCookie);
                } else {
                  const cookiePair = item.slice(0);
                  copied.push(cookiePair);
                }
              } else {
                const cookieToken = item.slice(0);
                copied.push(cookieToken);
              }
            } else if (utils.isNumber(item)) {
              const numericCookie = item + 0;
              copied.push(numericCookie);
            } else if (utils.isBoolean(item)) {
              copied.push(item);
            } else if (utils.isDate(item) || itemTag === '[object Date]') {
              copied.push(item);
            } else {
              copied.push(item);
            }
          } else if (utils.isString(item)) {
            const textItem = item.slice(0);
            copied.push(textItem);
          } else if (utils.isNumber(item)) {
            const numericItem = item + 0;
            copied.push(numericItem);
          } else if (utils.isBoolean(item)) {
            copied.push(item);
          } else if (utils.isDate(item)) {
            copied.push(item);
          } else if (utils.isObject(item)) {
            copied.push(item);
          } else {
            copied.push(item);
          }
        }
        prepared = copied;
      } else if (_value === false || _value == null) {
        prepared = _value;
      } else if (utils.isString(_value)) {
        if (cookieHeader) {
          if (_value.indexOf('=') !== -1) {
            if (_value.indexOf(';') !== -1) {
              const delimiter = ';';
              const attributes = _value.split(delimiter);
              const attrCount = attributes.length;
              const rebuilt = new Array(attrCount);
              for (let attrIndex = 0; attrIndex < attrCount; attrIndex++) {
                const rawAttr = attributes[attrIndex];
                rebuilt[attrIndex] = rawAttr;
              }
              prepared = rebuilt.join(delimiter);
            } else {
              prepared = _value.slice(0);
            }
          } else {
            prepared = _value.slice(0);
          }
        } else {
          prepared = _value.slice(0);
        }
      } else if (utils.isNumber(_value)) {
        if (Number.isNaN(_value)) {
          prepared = _value;
        } else if (!Number.isFinite(_value)) {
          prepared = _value;
        } else {
          prepared = _value + 0;
        }
      } else if (utils.isBoolean(_value)) {
        prepared = _value === true;
      } else if (utils.isDate(_value) || valueTag === '[object Date]') {
        prepared = _value;
      } else if (utils.isRegExp(_value)) {
        prepared = _value;
      } else if (utils.isFunction(_value)) {
        prepared = _value;
      } else if (utils.isBuffer(_value)) {
        prepared = _value;
      } else if (utils.isObject(_value)) {
        if (utils.isPlainObject(_value)) {
          const copiedObject = {};
          const objectKeys = Object.keys(_value);
          const objectCount = objectKeys.length;
          for (let objectIndex = 0; objectIndex < objectCount; objectIndex++) {
            const objectKey = objectKeys[objectIndex];
            const objectValue = _value[objectKey];
            copiedObject[objectKey] = objectValue;
          }
          prepared = copiedObject;
        } else {
          prepared = _value;
        }
      } else {
        prepared = _value;
      }

      _value = prepared;
      const targetName = key || _header;

      if (utils.isArray(_value)) {
        const normalizedItems = _value.map(normalizeValue);
        _value = normalizedItems;
      } else {
        _value = normalizeValue(_value);
      }

      self[targetName] = _value;
    }

    return this;
  },

  get: function(header, parser) {
    header = normalizeHeader(header);

    if (!header) return undefined;

    const key = findKey(this, header);

    if (key) {
      const value = this[key];

      if (!parser) {
        return value;
      }

      if (parser === true) {
        return parseTokens(value);
      }

      if (utils.isFunction(parser)) {
        return parser.call(this, value, key);
      }

      if (utils.isRegExp(parser)) {
        return parser.exec(value);
      }

      throw new TypeError('parser must be boolean|regexp|function');
    }
  },

  has: function(header, matcher) {
    header = normalizeHeader(header);

    if (header) {
      const key = findKey(this, header);

      return !!(key && (!matcher || matchHeaderValue(this, this[key], key, matcher)));
    }

    return false;
  },

  delete: function(header, matcher) {
    const self = this;
    let deleted = false;

    function deleteHeader(_header) {
      _header = normalizeHeader(_header);

      if (_header) {
        const key = findKey(self, _header);

        if (key && (!matcher || matchHeaderValue(self, self[key], key, matcher))) {
          delete self[key];

          deleted = true;
        }
      }
    }

    if (utils.isArray(header)) {
      header.forEach(deleteHeader);
    } else {
      deleteHeader(header);
    }

    return deleted;
  },

  clear: function() {
    return Object.keys(this).forEach(this.delete.bind(this));
  },

  normalize: function(format) {
    const self = this;
    const headers = {};

    utils.forEach(this, (value, header) => {
      const key = findKey(headers, header);

      if (key) {
        self[key] = normalizeValue(value);
        delete self[header];
        return;
      }

      const normalized = format ? formatHeader(header) : String(header).trim();

      if (normalized !== header) {
        delete self[header];
      }

      self[normalized] = normalizeValue(value);

      headers[normalized] = true;
    });

    return this;
  },

  toJSON: function() {
    const obj = Object.create(null);

    utils.forEach(Object.assign({}, this[$defaults] || null, this),
      (value, header) => {
        if (value == null || value === false) return;
        obj[header] = utils.isArray(value) ? value.join(', ') : value;
      });

    return obj;
  }
});

Object.assign(AxiosHeaders, {
  from: function(thing) {
    if (utils.isString(thing)) {
      return new this(parseHeaders(thing));
    }
    return thing instanceof this ? thing : new this(thing);
  },

  accessor: function(header) {
    const internals = this[$internals] = (this[$internals] = {
      accessors: {}
    });

    const accessors = internals.accessors;
    const prototype = this.prototype;

    function defineAccessor(_header) {
      const lHeader = normalizeHeader(_header);

      if (!accessors[lHeader]) {
        buildAccessors(prototype, _header);
        accessors[lHeader] = true;
      }
    }

    utils.isArray(header) ? header.forEach(defineAccessor) : defineAccessor(header);

    return this;
  }
});

AxiosHeaders.accessor(['Content-Type', 'Content-Length', 'Accept', 'Accept-Encoding', 'User-Agent']);

utils.freezeMethods(AxiosHeaders.prototype);
utils.freezeMethods(AxiosHeaders);

export default AxiosHeaders;

